#!/usr/bin/env bash
# =============================================================================
# =============================================================================
# InstantGram v1.19.6  -  clip sound editor, dashboard, account deletion,
#                         "Active now", disappearing messages
#
#   * Dashboard: a button under Edit profile / Share profile in the Me screen.
#     Holding a post or a clip still opens the insights of that one item.
#
#   * Editing a clip (Create -> clip -> Edit): audio tools and video tools.
#         Audio    where the song starts, song volume, original sound volume,
#                  fade in / fade out, voiceover (record over the clip)
#         Video    trim, mute, speed 0.5x - 2x, rotate
#     The Create preview plays exactly what will be posted (song in sync,
#     speed, rotation), and the clip is mixed that way when you post.
#     Not in this version: crop and reverse for videos.
#
#   * Deleting an account (developer tool on this computer):
#         bash tools/delete_user.sh setup             one time
#         bash tools/delete_user.sh <username|email>  one account
#         bash tools/delete_user.sh --leftovers       accounts deleted earlier
#     Removes their posts, clips, comments, likes, moments, messages, calls,
#     follows, files and the sign-in. People who chatted with them keep their
#     own messages and see "User not available".
#
#   * Chats: "Active now" / "Active 5m ago" under the name, a green dot in
#     the inbox for people who have the app open.
#
#   * Disappearing messages: in a chat, pull down and hold -> Off, After seen,
#     24 hours or 7 days. A note in the chat says who changed it.
#     firebase/firestore.rules is updated for it.
#
# Run from the project root:   bash update_v1196_sound_chats.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="b89d6bc6e8ac4ed5baef63facb959b9ac6dbc7915dfcfee97495c903fab30161"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/screens/chat/chat_options_sheet.dart ] || { echo "ERROR: v1.19.5 is not installed. Run update_v1195_longpress_analytics.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
# Some browsers save this file with Windows line endings (CRLF). Those
# extra characters corrupt the payload, so strip any control character
# sitting at the end of a line before decoding.
awk '/^__PAYLOAD__/{f=1;next} /^#/{f=0} f' "$0" | sed 's/[[:cntrl:]]*$//' | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       expected  $EXPECTED_SHA256"
  echo "       actual    $ACTUAL"
  echo "       your file is $(wc -c < "$0") bytes; it should be 552551 bytes."
  echo "       Smaller size = the download was cut short: download it again."
  echo "       Same size but still failing, run:"
  echo "         sed -i 's/[[:cntrl:]]*$//' $(basename "$0") && bash $(basename "$0")"
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
chmod +x tools/merge_audio.sh signer/setup.sh tools/delete_user.sh 2>/dev/null || true
# keys for the delete tool live in ~/.instantgram-admin, never in the project
touch .gitignore
for p in '*firebase-adminsdk*.json' '__pycache__/'; do
  grep -qxF "$p" .gitignore || echo "$p" >> .gitignore
done
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.19.6 is in place."
echo ""
echo "Still to do (once):"
echo "  * Deploy firebase/firestore.rules (Firebase console -> Firestore -> Rules,"
echo "    paste the file, Publish) or disappearing messages will be refused."
echo "  * For deleting accounts:  bash tools/delete_user.sh setup"
echo "    It tells you each step (service-account key, ADMIN_KEY in Vercel)."
exit 0

